import functools
from typing import ForwardRef, Dict, Any, get_type_hints
from fastapi.dependencies.utils import get_typed_signature
import inspect

def test_wrapped_method_type_inference():
    class MyClass:
        def method(self, x: "MyClass") -> None:
            pass

    @functools.wraps(MyClass.method)
    def wrapped(self, x: "MyClass") -> None:
        pass

    sig = get_typed_signature(wrapped)
    params = sig.parameters
    assert "x" in params
    print(f"Annotation for x: {params['x'].annotation}")
    assert params["x"].annotation is MyClass

if __name__ == "__main__":
    try:
        test_wrapped_method_type_inference()
        print("Test passed!")
    except Exception as e:
        print(f"Test failed: {e}")
        import traceback
        traceback.print_exc()
        exit(1)

