import functools
import pytest
from fastapi import FastAPI, Depends
from fastapi.dependencies.utils import get_typed_signature
from typing import ForwardRef, List, Any

# Define a type that will be used as a forward reference
class Item:
    pass

def wrapped_endpoint(item: "Item"):
    return {"item": item}

def wrapper(func):
    @functools.wraps(func)
    def wrapped(*args, **kwargs):
        return func(*args, **kwargs)
    return wrapped

@wrapper
def endpoint(item: "Item"):
    return {"item": item}

def test_wrapped_method_type_inference():
    # This should not raise NameError
    signature = get_typed_signature(endpoint)
    # The parameter 'item' should be resolved to the Item class
    param = signature.parameters["item"]
    assert param.annotation is Item

def test_fastapi_integration():
    app = FastAPI()

    @app.get("/")
    @wrapper
    def read_root(item: "Item"):
        return {"item": item}

    # Triggering the dependency resolution / signature extraction
    # through the internal mechanism that FastAPI uses during route addition.
    # In a real app, this happens in app.add_api_route.
    # We can check if the endpoint was added and its signature is correct.
    route = app.routes[0]
    # In FastAPI, the signature is usually processed when creating the Dependant
    # We can manually call get_typed_signature as a proxy for the logic used in get_dependant.
    signature = get_typed_signature(route.endpoint)
    assert signature.parameters["item"].annotation is Item

